<?php
require __DIR__.'/../bootstrap.php';require_admin();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');$uid=(int)post('user_id');if($action==='save_customer'&&$uid>0){$data=['region'=>post('region',''),'model_id'=>post('model_id',''),'endpoint_url'=>post('endpoint_url',''),'api_mode'=>post('api_mode',''),'transport'=>post('transport',''),'relay_url'=>post('relay_url','')];ai_save_user_settings($uid,$data);$notice='Customer AI settings updated.';}}
if(getv('download')==='csv'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="pocketcat-customer-ai.csv"');$out=fopen('php://output','w');fputcsv($out,['User','Email','Plan','API Key','AWS Access Key','AWS Secret','Session Token','Region','Model','API Mode','Transport','Relay URL','Relay Token','Endpoint','Updated']);$rows=db()->query("SELECT u.id,u.full_name,u.email,u.plan,s.bedrock_api_key_encrypted,s.aws_access_key_encrypted,s.aws_secret_key_encrypted,s.aws_session_token_encrypted,s.relay_token_encrypted,s.region,s.model_id,s.api_mode,s.transport,s.relay_url,s.endpoint_url,s.updated_at FROM users u LEFT JOIN user_ai_settings s ON s.user_id=u.id ORDER BY u.id DESC")->fetchAll();foreach($rows as $r){fputcsv($out,[$r['full_name'],$r['email'],$r['plan'],ai_mask_secret(decrypt_secret((string)$r['bedrock_api_key_encrypted'])),ai_mask_secret(decrypt_secret((string)$r['aws_access_key_encrypted'])),$r['aws_secret_key_encrypted']?'Configured':'Not configured',$r['aws_session_token_encrypted']?'Configured':'Not configured',$r['region']?:'Admin default',$r['model_id']?:'Admin default',$r['api_mode']?:'Admin default',$r['transport']?:'Admin default',$r['relay_url']?:'Admin default',$r['relay_token_encrypted']?'Configured':'Not configured',$r['endpoint_url']?:'Admin default',$r['updated_at']]);}fclose($out);exit;}
try{$rows=db()->query("SELECT u.id,u.full_name,u.email,u.username,u.plan,u.status,s.bedrock_api_key_encrypted,s.aws_access_key_encrypted,s.aws_secret_key_encrypted,s.aws_session_token_encrypted,s.relay_token_encrypted,s.region,s.model_id,s.endpoint_url,s.api_mode,s.transport,s.relay_url,s.updated_at FROM users u LEFT JOIN user_ai_settings s ON s.user_id=u.id ORDER BY u.id DESC")->fetchAll();}catch(Throwable $e){$rows=[];}
$title='Customer AI Access';require __DIR__.'/../includes/header.php';?><div class="page-head"><div><span class="eyebrow">ADMINISTRATION</span><h1>Customer AI Access</h1><p>Scrollable credential/status boxes, safe masked secrets, inline configuration editing and CSV export.</p></div><a class="btn secondary" href="/admin/ai-users/?download=csv">Download CSV</a></div><?php if($notice):?><div class="flash success"><?=e($notice)?></div><?php endif;?><section class="card table-wrap ai-users-wrap"><table class="data-table ai-users-table"><thead><tr><th>Customer</th><th>Plan</th><th>API Key</th><th>AWS Access</th><th>Secret</th><th>Session</th><th>Region</th><th>Model</th><th>Mode</th><th>Transport</th><th>Relay URL</th><th>Relay Token</th><th>Endpoint</th><th>Updated</th><th>Save</th></tr></thead><tbody><?php foreach($rows as $r): $fid='ai-save-'.$r['id']; ?><tr>
<td data-label="Customer"><form id="<?=$fid?>" method="post" style="display:none"><?=csrf_field()?><input type="hidden" name="action" value="save_customer"><input type="hidden" name="user_id" value="<?=$r['id']?>"></form><strong><?=e($r['full_name'])?></strong><br><span class="muted"><?=e($r['email'])?></span></td>
<td data-label="Plan"><?=e(ucfirst($r['plan']))?></td><td data-label="API Key"><div class="credential-box-row"><code class="credential-box"><?=e(ai_mask_secret(decrypt_secret((string)$r['bedrock_api_key_encrypted'])))?></code><button type="button" class="edit-btn" data-copy="<?=e(ai_mask_secret(decrypt_secret((string)$r['bedrock_api_key_encrypted'])))?>">Copy</button></div></td><td data-label="AWS Access Key"><div class="credential-box-row"><code class="credential-box"><?=e(ai_mask_secret(decrypt_secret((string)$r['aws_access_key_encrypted'])))?></code><button type="button" class="edit-btn" data-copy="<?=e(ai_mask_secret(decrypt_secret((string)$r['aws_access_key_encrypted'])))?>">Copy</button></div></td><td data-label="AWS Secret"><div class="credential-box-row"><span class="credential-box"><?=$r['aws_secret_key_encrypted']?'Configured':'Not configured'?></span><button type="button" class="edit-btn" data-copy="<?=e($r['aws_secret_key_encrypted']?'Configured':'Not configured')?>">Copy</button></div></td><td data-label="Session Token"><div class="credential-box-row"><span class="credential-box"><?=$r['aws_session_token_encrypted']?'Configured':'Not configured'?></span><button type="button" class="edit-btn" data-copy="<?=e($r['aws_session_token_encrypted']?'Configured':'Not configured')?>">Copy</button></div></td>
<td data-label="Region"><input name="region" form="<?=$fid?>" value="<?=e($r['region']??'')?>"></td><td data-label="Model"><input name="model_id" form="<?=$fid?>" value="<?=e($r['model_id']??'')?>"></td><td data-label="API Mode"><select name="api_mode" form="<?=$fid?>"><option value="openai" <?=($r['api_mode']??'')==='openai'?'selected':''?>>OpenAI</option><option value="responses" <?=($r['api_mode']??'')==='responses'?'selected':''?>>Responses</option><option value="converse" <?=($r['api_mode']??'')==='converse'?'selected':''?>>Converse</option></select></td><td data-label="Transport"><select name="transport" form="<?=$fid?>"><option value="relay" <?=($r['transport']??'')==='relay'?'selected':''?>>Relay</option><option value="auto" <?=($r['transport']??'')==='auto'?'selected':''?>>Auto</option><option value="direct" <?=($r['transport']??'')==='direct'?'selected':''?>>Direct</option></select></td>
<td data-label="Relay URL"><div class="credential-box-row"><code class="credential-box"><?=e($r['relay_url']?:'Admin default')?></code><button type="button" class="edit-btn" data-copy="<?=e($r['relay_url']??'')?>">Copy</button></div><input name="relay_url" form="<?=$fid?>" value="<?=e($r['relay_url']??'')?>" placeholder="Inline edit"></td>
<td data-label="Relay Token"><div class="credential-box-row"><span class="credential-box"><?=$r['relay_token_encrypted']?'Configured':'Not configured'?></span><button type="button" class="edit-btn" data-copy="<?=e($r['relay_token_encrypted']?'Configured':'Not configured')?>">Copy</button></div></td><td data-label="Endpoint"><div class="credential-box-row"><code class="credential-box"><?=e($r['endpoint_url']?:'Admin default')?></code><button type="button" class="edit-btn" data-copy="<?=e($r['endpoint_url']??'')?>">Copy</button></div><input name="endpoint_url" form="<?=$fid?>" value="<?=e($r['endpoint_url']??'')?>"></td><td data-label="Updated"><?=e($r['updated_at']?:'—')?></td><td data-label="Actions"><button form="<?=$fid?>" class="btn small">Save</button></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="15">No customers found.</td></tr><?php endif;?></tbody></table></section><section class="card"><h3>Security</h3><p class="muted">Raw customer secrets are never exposed by this table or CSV. Copy actions are limited to visible non-secret URLs/values; secret cells expose only a masked status/suffix.</p></section><script>document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{const v=b.dataset.copy||'';if(!v)return;b.textContent='Copying…';try{await navigator.clipboard.writeText(v);b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1000)}catch(e){prompt('Copy',v);b.textContent='Copy'}}));</script><?php require __DIR__.'/../includes/footer.php';?>
